const outliers = $('Read Outliers Dashboard').all().map(i => i.json);
const yoy      = $('Read YoY Comparison').all().map(i => i.json);

const today = new Date().toLocaleDateString('en-IN', {
  day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Asia/Kolkata'
});

const fire    = outliers.filter(r => r['Flag'] === '🔥');
const spark   = outliers.filter(r => r['Flag'] === '⚡');
const growing = outliers.filter(r => r['Flag'] === '📈');
const drop    = outliers.filter(r => r['Flag'] === '📉');
const yoyFire = yoy.filter(r => r['Flag'] === '🔥');
const yoyDrop = yoy.filter(r => r['Flag'] === '📉');

const SHEET = 'https://docs.google.com/spreadsheets/d/1fMV0KVGkq53evsv7mffxmjSwbwDNYVpgq3CRPHkSOZ8';

const css = `
  body { margin:0; padding:0; background:#f4f4f5; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; }
  .wrap { max-width:680px; margin:32px auto; background:#fff; border-radius:10px; overflow:hidden; box-shadow:0 2px 12px rgba(0,0,0,0.08); }
  .header { background:#111; padding:24px 32px; }
  .header h1 { margin:0; color:#fff; font-size:20px; font-weight:700; }
  .header p { margin:6px 0 0; color:#aaa; font-size:13px; }
  .body { padding:28px 32px; }
  .section-title { font-size:15px; font-weight:700; margin:24px 0 10px; display:flex; align-items:center; gap:8px; }
  .badge { display:inline-block; font-size:11px; font-weight:600; padding:2px 8px; border-radius:20px; margin-left:6px; }
  .badge-red { background:#fee2e2; color:#b91c1c; }
  .badge-green { background:#dcfce7; color:#15803d; }
  .badge-blue { background:#dbeafe; color:#1d4ed8; }
  .badge-gray { background:#f1f5f9; color:#475569; }
  table { width:100%; border-collapse:collapse; font-size:13px; }
  th { background:#f8fafc; padding:8px 12px; text-align:left; font-weight:600; color:#64748b; border-bottom:2px solid #e2e8f0; }
  td { padding:8px 12px; border-bottom:1px solid #f1f5f9; color:#1e293b; }
  tr:last-child td { border-bottom:none; }
  .empty { color:#94a3b8; font-style:italic; padding:12px; text-align:center; }
  .footer { background:#f8fafc; padding:16px 32px; text-align:center; font-size:11px; color:#94a3b8; border-top:1px solid #e2e8f0; }
  .btn { display:inline-block; margin-top:6px; padding:8px 20px; background:#111; color:#fff; text-decoration:none; border-radius:6px; font-size:13px; font-weight:600; }
`;

function tableRows(rows, cols) {
  if (!rows.length) return `<tr><td colspan="${cols.length}" class="empty">None today</td></tr>`;
  return rows.slice(0, 10).map(r =>
    `<tr>${cols.map(c => `<td>${r[c] !== undefined ? r[c] : '-'}</td>`).join('')}</tr>`
  ).join('');
}

function section(emoji, title, badgeClass, count, cols, rows) {
  return `
    <div class="section-title">${emoji} ${title} <span class="badge ${badgeClass}">${count}</span></div>
    <table>
      <tr>${cols.map(c => `<th>${c}</th>`).join('')}</tr>
      ${tableRows(rows, cols)}
    </table>`;
}

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><style>${css}</style></head>
<body>
<div class="wrap">
  <div class="header">
    <h1>Swiss Beauty - Sales Outliers</h1>
    <p>${today} &nbsp;|&nbsp; Auto-generated report</p>
  </div>
  <div class="body">
    <p style="margin:0 0 20px;color:#64748b;font-size:13px;">
      <a href="${SHEET}" style="color:#2563eb;font-weight:600;">Open Full Google Sheet</a>
    </p>

    ${section('🔥', 'Confirmed Spikes', 'badge-red', fire.length,
      ['Product', 'Units - Last 7D', '7D vs Prior 7D (Units %)', '7D vs Prior 7D (Rev %)'],
      fire)}

    ${section('⚡', 'Recent Burst', 'badge-blue', spark.length,
      ['Product', 'Units - Last 7D', '7D vs Prior 7D (Units %)', '1M vs Prior 1M (Units %)'],
      spark)}

    ${section('📈', 'Growing', 'badge-green', growing.length,
      ['Product', 'Units - Last 7D', '7D vs Prior 7D (Units %)', '1Q vs Prior 1Q (Units %)'],
      growing)}

    ${section('📉', 'Declining', 'badge-gray', drop.length,
      ['Product', 'Units - Last 7D', '7D vs Prior 7D (Units %)', '1Q vs Prior 1Q (Units %)'],
      drop)}

    <hr style="margin:28px 0;border:none;border-top:1px solid #e2e8f0;">
    <div class="section-title">📅 YoY Highlights</div>
    <table>
      <tr><th>Product</th><th>Flag</th><th>Month YoY (Units %)</th><th>Quarter YoY (Units %)</th></tr>
      ${yoyFire.length + yoyDrop.length === 0
        ? '<tr><td colspan="4" class="empty">No strong YoY signals today</td></tr>'
        : tableRows([...yoyFire, ...yoyDrop].slice(0,8),
            ['Product', 'Flag', 'Month YoY Uplift (Units %)', 'Quarter YoY Uplift (Units %)'])}
    </table>
  </div>
  <div class="footer">
    Auto-generated by Swiss Beauty Sales Outliers automation &nbsp;|&nbsp;
    <a href="${SHEET}" style="color:#2563eb;">View Sheet</a>
  </div>
</div>
</body></html>`;

const subject = `Swiss Beauty Outliers - ${today} | 🔥${fire.length} Spikes  ⚡${spark.length} Bursts  📉${drop.length} Drops`;

return [{ json: { html, subject, today,
  counts: { fire: fire.length, spark: spark.length, growing: growing.length, drop: drop.length }
} }];
